"""Compressed byte-sequence programs used by the offline evidence pipeline.

The representation is an immutable rope.  Operations keep exact lengths and
allow fingerprints, bounded reads and line searches without expanding repeated
data.  Only the public operations needed by the protocol are exposed.
"""
from __future__ import annotations

import ast
import hashlib
import keyword
import re
from bisect import bisect_right
from typing import Iterable, Optional, Tuple

MAX = (1 << 63) - 1
MASK64 = (1 << 64) - 1
_RANDOM_TOKEN = "<<random_string>>"


# ---------------------------------------------------------------------------
# Rope nodes


class _Node:
    __slots__ = ("size", "_fp")

    def __init__(self, size: int):
        self.size = size
        self._fp = None


class _Lit(_Node):
    __slots__ = ("data",)

    def __init__(self, data: bytes):
        super().__init__(len(data))
        self.data = data


class _Cat(_Node):
    __slots__ = ("parts",)

    def __init__(self, parts: Tuple[_Node, ...]):
        super().__init__(sum(p.size for p in parts))
        self.parts = parts


class _Rep(_Node):
    __slots__ = ("part", "count")

    def __init__(self, part: _Node, count: int):
        super().__init__(part.size * count)
        self.part = part
        self.count = count


class _Slice(_Node):
    __slots__ = ("part", "start", "end")

    def __init__(self, part: _Node, start: int, end: int):
        super().__init__(end - start)
        self.part = part
        self.start = start
        self.end = end


_EMPTY = _Lit(b"")


# ---------------------------------------------------------------------------
# Basic constructors


def literal(data):
    if not isinstance(data, bytes):
        raise ValueError("byte literal")
    if len(data) > MAX:
        raise ValueError("byte sequence too long")
    if not data:
        return _EMPTY
    return _Lit(data)


def concat(a, b):
    if not isinstance(a, _Node) or not isinstance(b, _Node):
        raise ValueError("concatenation operands")
    if a.size == 0:
        return b
    if b.size == 0:
        return a
    total = a.size + b.size
    if total > MAX:
        raise ValueError("byte sequence too long")
    return _Cat((a, b))


def concat_many(parts):
    kept = []
    total = 0
    for part in parts:
        if not isinstance(part, _Node):
            raise ValueError("concatenation operand")
        if part.size:
            kept.append(part)
            total += part.size
            if total > MAX:
                raise ValueError("byte sequence too long")
    if not kept:
        return _EMPTY
    if len(kept) == 1:
        return kept[0]
    return _Cat(tuple(kept))


def repeat(node, count):
    if not isinstance(node, _Node):
        raise ValueError("repetition operand")
    if type(count) is not int or count < 0 or count > MAX:
        raise ValueError("repetition count")
    if node.size == 0 or count == 0:
        return _EMPTY
    if count == 1:
        return node
    total = node.size * count
    if total > MAX:
        raise ValueError("byte sequence too long")
    return _Rep(node, count)


def cut(node, start, end):
    if not isinstance(node, _Node):
        raise ValueError("slice operand")
    if (type(start) is not int or type(end) is not int or
            start < 0 or end < start or end > node.size):
        raise ValueError("slice bounds")
    if start == end:
        return _EMPTY
    if start == 0 and end == node.size:
        return node

    # Collapse nested slices without recursion.
    offset = 0
    base = node
    while isinstance(base, _Slice):
        offset += base.start
        base = base.part
    start += offset
    end += offset
    if start == 0 and end == base.size:
        return base
    if start == end:
        return _EMPTY
    if isinstance(base, _Lit):
        return literal(base.data[start:end])
    return _Slice(base, start, end)


def size(node):
    return node.size if isinstance(node, _Node) else 0


# ---------------------------------------------------------------------------
# Fingerprints


def _pow257(n: int) -> int:
    return pow(257, n, 1 << 64)


def _lit_fp(data: bytes) -> Tuple[int, int]:
    h = 0
    for value in data:
        h = ((h * 257) + value + 1) & MASK64
    return len(data), h


def _combine_fp(a: Tuple[int, int], b: Tuple[int, int]) -> Tuple[int, int]:
    an, ah = a
    bn, bh = b
    if bn == 0:
        return an, ah
    return an + bn, ((ah * _pow257(bn)) + bh) & MASK64


def _geom_sum(q: int, count: int) -> int:
    """1 + q + ... + q**(count-1), modulo 2**64."""
    result_pow = 1
    result_sum = 0
    block_pow = q
    block_sum = 1
    n = count
    while n:
        if n & 1:
            result_sum = (result_sum + result_pow * block_sum) & MASK64
            result_pow = (result_pow * block_pow) & MASK64
        block_sum = (block_sum + block_pow * block_sum) & MASK64
        block_pow = (block_pow * block_pow) & MASK64
        n >>= 1
    return result_sum


def _rep_fp(part: _Node, count: int) -> Tuple[int, int]:
    if count == 0 or part.size == 0:
        return 0, 0
    pn, ph = full_fp(part)
    q = _pow257(pn)
    return pn * count, (ph * _geom_sum(q, count)) & MASK64


def full_fp(node) -> Tuple[int, int]:
    """Return (length, checksum) for an entire rope node."""
    if not isinstance(node, _Node):
        return 0, 0
    if node._fp is not None:
        return node._fp

    # Iterative post-order over the DAG.  Repeated definitions can form long
    # reference chains; this avoids exhausting the Python call stack.
    stack = [(node, False)]
    while stack:
        current, expanded = stack.pop()
        if current._fp is not None:
            continue
        if isinstance(current, _Lit):
            current._fp = _lit_fp(current.data)
            continue
        if not expanded:
            stack.append((current, True))
            if isinstance(current, _Cat):
                for child in current.parts:
                    if child._fp is None:
                        stack.append((child, False))
            elif isinstance(current, _Rep):
                if current.part._fp is None:
                    stack.append((current.part, False))
            elif isinstance(current, _Slice):
                if current.part._fp is None:
                    stack.append((current.part, False))
            else:  # pragma: no cover - constructors are closed
                raise ValueError("unknown rope node")
            continue

        if isinstance(current, _Cat):
            result = (0, 0)
            for child in current.parts:
                result = _combine_fp(result, child._fp)
            current._fp = result
        elif isinstance(current, _Rep):
            current._fp = _rep_fp(current.part, current.count)
        elif isinstance(current, _Slice):
            current._fp = fp_range(current.part, current.start, current.end)
        else:  # pragma: no cover
            raise ValueError("unknown rope node")
    return node._fp


def fp_range(node, start: int, end: int) -> Tuple[int, int]:
    """Fingerprint bytes node[start:end] without materializing the range."""
    if not isinstance(node, _Node):
        if start == 0 and end == 0:
            return 0, 0
        raise ValueError("range operand")
    if (type(start) is not int or type(end) is not int or
            start < 0 or end < start or end > node.size):
        raise ValueError("range bounds")
    if start == end:
        return 0, 0
    if start == 0 and end == node.size:
        return full_fp(node)

    result = (0, 0)
    stack = [(node, start, end)]
    while stack:
        current, lo, hi = stack.pop()
        if lo >= hi:
            continue
        if lo == 0 and hi == current.size:
            result = _combine_fp(result, full_fp(current))
            continue
        if isinstance(current, _Lit):
            result = _combine_fp(result, _lit_fp(current.data[lo:hi]))
            continue
        if isinstance(current, _Cat):
            pieces = []
            offset = 0
            for child in current.parts:
                child_end = offset + child.size
                a = max(lo, offset)
                b = min(hi, child_end)
                if a < b:
                    pieces.append((child, a - offset, b - offset))
                offset = child_end
                if offset >= hi:
                    break
            stack.extend(reversed(pieces))
            continue
        if isinstance(current, _Rep):
            pattern = current.part
            p = pattern.size
            first = lo // p
            last = (hi - 1) // p
            if first == last:
                base = first * p
                stack.append((pattern, lo - base, hi - base))
                continue
            pieces = []
            left_start = lo - first * p
            if left_start < p:
                pieces.append((pattern, left_start, p))
            full_count = last - first - 1
            if full_count:
                pieces.append((_Rep(pattern, full_count), 0, p * full_count))
            right_end = hi - last * p
            if right_end:
                pieces.append((pattern, 0, right_end))
            stack.extend(reversed(pieces))
            continue
        if isinstance(current, _Slice):
            base = current.start
            stack.append((current.part, base + lo, base + hi))
            continue
        raise ValueError("unknown rope node")
    return result


def fingerprint(node):
    n, h = full_fp(node)
    return {"n": n, "h": f"{h:016x}"}


def fingerprint_bytes(data: bytes):
    n, h = _lit_fp(data)
    return {"n": n, "h": f"{h:016x}"}


# ---------------------------------------------------------------------------
# Bounded reads and line access


def read_range(node, start: int, end: int, limit: int = 65536) -> bytes:
    """Materialize a bounded byte range."""
    if not isinstance(node, _Node):
        if start == 0 and end == 0:
            return b""
        raise ValueError("range operand")
    if (type(start) is not int or type(end) is not int or
            start < 0 or end < start or end > node.size):
        raise ValueError("range bounds")
    length = end - start
    if length > limit:
        raise ValueError("bounded materialization")
    if length == 0:
        return b""

    out = bytearray()
    stack = [(node, start, end)]
    while stack:
        current, lo, hi = stack.pop()
        if lo >= hi:
            continue
        if isinstance(current, _Lit):
            out.extend(current.data[lo:hi])
            continue
        if isinstance(current, _Cat):
            pieces = []
            offset = 0
            for child in current.parts:
                child_end = offset + child.size
                a = max(lo, offset)
                b = min(hi, child_end)
                if a < b:
                    pieces.append((child, a - offset, b - offset))
                offset = child_end
                if offset >= hi:
                    break
            stack.extend(reversed(pieces))
            continue
        if isinstance(current, _Rep):
            pattern = current.part
            p = pattern.size
            if isinstance(pattern, _Lit):
                # Fast path for the overwhelmingly common repeated-literal
                # case, including ranges at very large offsets.
                offset_in_pattern = lo % p
                needed = length
                repeats = (offset_in_pattern + needed + p - 1) // p
                data = (pattern.data * repeats)[offset_in_pattern:offset_in_pattern + needed]
                out.extend(data)
                length = 0
                break
            first = lo // p
            last = (hi - 1) // p
            if first == last:
                base = first * p
                stack.append((pattern, lo - base, hi - base))
                continue
            pieces = []
            left_start = lo - first * p
            if left_start < p:
                pieces.append((pattern, left_start, p))
            full_count = last - first - 1
            if full_count:
                # The requested range is bounded, so a literal-free huge
                # number of full repeats is still only visited as one special
                # marker.  Expand it only as necessary below.
                pieces.append((_Rep(pattern, full_count), 0, p * full_count))
            right_end = hi - last * p
            if right_end:
                pieces.append((pattern, 0, right_end))
            stack.extend(reversed(pieces))
            continue
        if isinstance(current, _Slice):
            base = current.start
            stack.append((current.part, base + lo, base + hi))
            continue
        raise ValueError("unknown rope node")
    return bytes(out[:length])


def materialize(node, limit: int = 65536) -> bytes:
    if not isinstance(node, _Node):
        return b""
    if node.size > limit:
        raise ValueError("bounded materialization")
    return read_range(node, 0, node.size, limit)


def next_lf(node, start: int = 0):
    """Offset of the first LF at or after start, or -1 (bounded chunks)."""
    if not isinstance(node, _Node):
        return -1
    if start < 0:
        raise ValueError("line start")
    total = node.size
    chunk = 65536
    pos = start
    while pos < total:
        end = min(total, pos + chunk)
        data = read_range(node, pos, end, chunk)
        found = data.find(b"\n")
        if found >= 0:
            return pos + found
        pos = end
    return -1


# ---------------------------------------------------------------------------
# Capture view: a concatenation of attribution-labelled parts


class Capture:
    """A random-access view over a channel's concatenated parts."""

    __slots__ = ("parts", "owners", "starts", "ends", "total")

    def __init__(self, parts):
        # parts is an iterable of (owner, node)
        self.parts = list(parts)
        self.owners = [owner for owner, _ in self.parts]
        starts = []
        ends = []
        cursor = 0
        for _, node in self.parts:
            starts.append(cursor)
            cursor += node.size
            if cursor > MAX:
                raise ValueError("channel too long")
            ends.append(cursor)
        self.starts = starts
        self.ends = ends
        self.total = cursor

    def read(self, start: int, end: int, limit: int = 65536) -> bytes:
        if (type(start) is not int or type(end) is not int or
                start < 0 or end < start or end > self.total):
            raise ValueError("capture range")
        length = end - start
        if length > limit:
            raise ValueError("bounded materialization")
        if length == 0:
            return b""
        result = bytearray()
        index = bisect_right(self.ends, start)
        while index < len(self.parts) and start < end:
            node = self.parts[index][1]
            part_start = self.starts[index]
            part_end = self.ends[index]
            a = max(start, part_start)
            b = min(end, part_end)
            if a < b:
                result.extend(read_range(node, a - part_start, b - part_start,
                                         length - len(result)))
            index += 1
        return bytes(result)

    def fp_range(self, start: int, end: int) -> Tuple[int, int]:
        if (type(start) is not int or type(end) is not int or
                start < 0 or end < start or end > self.total):
            raise ValueError("capture range")
        if start == end:
            return 0, 0
        result = (0, 0)
        index = bisect_right(self.ends, start)
        while index < len(self.parts) and start < end:
            node = self.parts[index][1]
            part_start = self.starts[index]
            a = max(start, part_start)
            b = min(end, self.ends[index])
            if a < b:
                result = _combine_fp(result, fp_range(node, a - part_start,
                                                      b - part_start))
            index += 1
        return result

    def fingerprint(self):
        result = (0, 0)
        for _, node in self.parts:
            result = _combine_fp(result, full_fp(node))
        n, h = result
        return {"n": n, "h": f"{h:016x}"}

    def owner_at(self, offset: int):
        if not (0 <= offset < self.total):
            raise ValueError("capture offset")
        index = bisect_right(self.ends, offset)
        return self.owners[index]

    def owners_for(self, start: int, end: int):
        """Merged positive byte counts for [start,end), in first-seen order."""
        if not (0 <= start <= end <= self.total):
            raise ValueError("capture range")
        merged = []
        positions = {}
        index = bisect_right(self.ends, start)
        cursor = start
        while index < len(self.parts) and cursor < end:
            part_start = self.starts[index]
            part_end = self.ends[index]
            a = max(cursor, part_start)
            b = min(end, part_end)
            if a < b:
                label = self.owners[index]
                count = b - a
                if label in positions:
                    merged[positions[label]][1] += count
                else:
                    positions[label] = len(merged)
                    merged.append([label, count])
                cursor = b
            index += 1
        return merged

    def committed_after(self, request_ends):
        counts = []
        for boundary in self.ends:
            counts.append(bisect_right(request_ends, boundary))
        return counts


# ---------------------------------------------------------------------------
# Expression parsing / context


_IDENT = re.compile(r"[A-Za-z][A-Za-z0-9_]{0,31}\Z", re.ASCII)


def _check_depth(root) -> int:
    maximum = 0
    stack = [(root, 0)]
    while stack:
        node, depth = stack.pop()
        if depth > maximum:
            maximum = depth
            if maximum > 128:
                raise ValueError("expression nesting depth")
        for child in ast.iter_child_nodes(node):
            stack.append((child, depth + 1))
    return maximum


class Context:
    def __init__(self, definitions, seed):
        self.seed = seed
        self.defs = {}
        self._definition_mode = True
        self._cache = {}
        for row in definitions:
            if type(row) is not list or len(row) != 2:
                raise ValueError("definition row")
            name, source = row
            if type(name) is not str or not _IDENT.fullmatch(name) or keyword.iskeyword(name):
                raise ValueError("definition name")
            if name in self.defs:
                raise ValueError("duplicate definition")
            if type(source) is not str or len(source) > 8192:
                raise ValueError("definition source")
            source.encode("utf8")
            node = self.expression(source)
            if not isinstance(node, _Node):
                raise ValueError("definition is not bytes")
            self.defs[name] = node
        self._definition_mode = False
        self._cache = {}

    def expression(self, text):
        if type(text) is not str:
            raise ValueError("expression type")
        if len(text) > 65536:
            raise ValueError("expression source")
        text.encode("utf8")
        if not self._definition_mode:
            cached = self._cache.get(text)
            if cached is not None:
                return cached
        tree = ast.parse(text, mode="eval")
        _check_depth(tree.body)
        value = self._eval(tree.body)
        if not self._definition_mode:
            self._cache[text] = value
        return value

    def _constant_int(self, node, what="integer"):
        if not isinstance(node, ast.Constant) or type(node.value) is not int:
            raise ValueError(what)
        value = node.value
        if value < 0 or value > MAX:
            raise ValueError(what)
        return value

    def _eval(self, node):
        if isinstance(node, ast.Constant):
            value = node.value
            if type(value) is str:
                return literal(value.encode("utf8"))
            if type(value) is bytes:
                return literal(value)
            if type(value) is int:
                if value < 0 or value > MAX:
                    raise ValueError("integer literal")
                return value
            raise ValueError("constant")

        if isinstance(node, ast.Name):
            if node.id not in self.defs:
                raise ValueError("unknown definition")
            return self.defs[node.id]

        if isinstance(node, ast.BinOp):
            left = self._eval(node.left)
            right = self._eval(node.right)
            if isinstance(node.op, ast.Add):
                if not isinstance(left, _Node) or not isinstance(right, _Node):
                    raise ValueError("addition operands")
                return concat(left, right)
            if isinstance(node.op, ast.Mult):
                if isinstance(left, _Node) and type(right) is int:
                    return repeat(left, right)
                if type(left) is int and isinstance(right, _Node):
                    return repeat(right, left)
                raise ValueError("repetition operands")
            raise ValueError("operator")

        if isinstance(node, ast.Subscript):
            base = self._eval(node.value)
            if not isinstance(base, _Node) or not isinstance(node.slice, ast.Slice):
                raise ValueError("slice operand")
            sl = node.slice
            if sl.step is not None:
                raise ValueError("slice step")
            if sl.lower is None:
                lo = 0
            else:
                lo = self._constant_int(sl.lower, "slice endpoint")
            if sl.upper is None:
                hi = base.size
            else:
                hi = self._constant_int(sl.upper, "slice endpoint")
            if lo > hi or hi > base.size:
                raise ValueError("slice bounds")
            return cut(base, lo, hi)

        raise ValueError("expression syntax")

    def template(self, value, coordinate):
        if type(value) is not str:
            raise ValueError("template type")
        if len(value) > 65536:
            raise ValueError("template source")
        value.encode("utf8")
        if value.startswith("{{") and value.endswith("}}"):
            expression = value[2:-2].strip()
            result = self.expression(expression)
            if not isinstance(result, _Node):
                raise ValueError("template is not bytes")
            return result

        parts = []
        position = 0
        occurrence = 0
        token_length = len(_RANDOM_TOKEN)
        while True:
            found = value.find(_RANDOM_TOKEN, position)
            if found < 0:
                parts.append(value[position:])
                break
            parts.append(value[position:found])
            material = f"{self.seed}/{coordinate}/{occurrence}".encode("utf8")
            parts.append(hashlib.sha256(material).hexdigest()[:20])
            occurrence += 1
            position = found + token_length
        return literal("".join(parts).encode("utf8"))
